  const legacyTrend = ref<TrendData>({ current: '12h', liquidNormalRange: [60, 90], temperatureNormalRange: [18, 28], periods: {} });
  const activeMonth = ref(new Date().getMonth() + 1), monthMenuOpen = ref(false), monthMenuRef = ref<HTMLElement | null>(null), rangeMenuOpen = ref(false), rangeError = ref(''), trendBrand = ref('all');
  const todayIso = formatDate(new Date()), appliedStart = ref(formatDate(addDays(new Date(), -29))), appliedEnd = ref(todayIso), draftStart = ref(appliedStart.value), draftEnd = ref(appliedEnd.value), startView = ref(monthStart(parseDate(appliedStart.value))), endView = ref(monthStart(parseDate(appliedEnd.value)));
  let clockTimer: ReturnType<typeof setInterval> | undefined, pollTimer: ReturnType<typeof setTimeout> | undefined, requestSeq = 0, polling = false, resumeWhenVisible = false, failures = 0, pollDelay = 300000;

