  const inventoryMarkup = computed(() => buildInventory()), riskMarkup = computed(() => buildRisk()), energyMarkup = computed(() => buildEnergy()), environmentMarkup = computed(() => buildEnvironment()), trendMarkup = computed(() => buildTrend());

  function n(v: unknown, fallback = 0) { const x = Number(v); return Number.isFinite(x) ? x : fallback; }
  function esc(v: unknown) { return String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c] || c); }
  function fmt(v: unknown, d = 1) { return n(v).toLocaleString('zh-CN', { minimumFractionDigits: d, maximumFractionDigits: d }); }
  function normalizeWorkshopIndex(v: unknown) { const raw = Array.isArray(v) ? v[0] : v, i = Number(raw); return Number.isInteger(i) && i >= 0 && i <= 3 ? i : 0; }
  function dailyTransferBody() {
