    const maxValue = Math.max(...items.flatMap((item) => [n(item.planned), n(item.actual)]), 1);
    const axisMax = Math.max(100, Math.ceil(maxValue / 100) * 100);
    const plot = { left: 37, right: 378, top: 22, bottom: 122 };
    const centers = [122, 293], barWidth = 31;
    const valueY = (value: unknown) => plot.bottom - Math.max(0, Math.min(axisMax, n(value))) / axisMax * (plot.bottom - plot.top);
