      return `<rect class="monthly-plan-bar" style="--bar-index:${index}" data-daily-index="${index}" x="${center - barWidth - 2}" y="${plannedY.toFixed(2)}" width="${barWidth}" height="${(plot.bottom - plannedY).toFixed(2)}"></rect><rect class="monthly-actual-bar" style="--bar-index:${index}" data-daily-index="${index}" x="${center + 2}" y="${actualY.toFixed(2)}" width="${barWidth}" height="${(plot.bottom - actualY).toFixed(2)}"></rect><text class="daily-bar-value plan" x="${center - barWidth / 2 - 2}" y="${Math.max(13, plannedY - 5).toFixed(2)}">${planned.toFixed(1)}</text><text class="daily-bar-value actual" x="${center + barWidth / 2 + 2}" y="${Math.max(13, actualY - 5).toFixed(2)}">${actual.toFixed(1)}</text><text class="daily-group-label" x="${center}" y="143">${esc(item.shortName || item.name)}</text>`;
