    const completion = totals.planned ? totals.actual / totals.planned * 100 : n(transfer.value.completion), variance = totals.actual - totals.planned;
    const net = Number.isFinite(Number(transfer.value.net)) ? n(transfer.value.net) : n(items[0]?.actual) - n(items[1]?.actual);
    return `<div class="monthly-meta"><span class="monthly-unit">单位：吨</span><div class="monthly-legend"><span><i></i>计划调拨量</span><span><i class="actual"></i>实际调拨量</span></div></div><div class="monthly-kpis"><div class="monthly-kpi">完成率 <b>${completion.toFixed(1)}%</b></div><div class="monthly-kpi">偏差 <b>${variance.toLocaleString('zh-CN', { minimumFractionDigits: 1, maximumFractionDigits: 1 })}</b><small>吨</small></div><div class="monthly-kpi daily-net-kpi">净流入 <b>${net.toFixed(1)}</b><small>吨</small></div></div><div class="monthly-chart daily-chart"><svg viewBox="0 0 415 154" preserveAspectRatio="none" role="img" aria-label="今日入罐与出罐计划调拨量和实际调拨量柱状图"><defs><linearGradient id="planGradient" x1="0" y1="0" x2="0" y2="1"><stop class="monthly-plan-start" offset="0"></stop><stop class="monthly-plan-end" offset="1"></stop></linearGradient><linearGradient id="actualGradient" x1="0" y1="0" x2="0" y2="1"><stop class="monthly-actual-start" offset="0"></stop><stop class="monthly-actual-end" offset="1"></stop></linearGradient></defs>${zones}${grid}${bars}</svg><div class="monthly-tooltip daily-tooltip" role="status"><strong></strong><span>计划调拨量<b class="tooltip-planned"></b></span><span class="actual">实际调拨量<b class="tooltip-actual"></b></span></div></div>`;
  }
  function transferBody(plan: TransferPlan, digits = 1, net?: number) { const items = plan.items || []; if (!items.length) return '<div class="monthly-meta"><span class="monthly-unit">单位：吨</span></div><div class="monthly-kpis"><div class="monthly-kpi">完成率 <b>--</b></div><div class="monthly-kpi">偏差 <b>--</b><small>吨</small></div></div><div class="monthly-chart"><div class="monthly-empty-state">暂无计划执行数据</div></div>'; const max = Math.max(1, n(plan.axisMax, 1000)), step = 335 / items.length, width = Math.min(14, step * .25), y = (v: unknown) => 126 - Math.max(0, Math.min(max, n(v))) / max * 118, totals = items.reduce((s, i) => ({ p: s.p + n(i.planned), a: s.a + n(i.actual) }), { p: 0, a: 0 }), completion = totals.p ? totals.a / totals.p * 100 : n(plan.completion), variance = totals.a - totals.p; const grid = Array.from({ length: 6 }, (_, i) => { const value = max - i * max / 5, yy = y(value); return `<line class="monthly-grid" x1="39" y1="${yy}" x2="374" y2="${yy}"></line><text class="monthly-axis-label" x="32" y="${yy + 4}" text-anchor="end">${Math.round(value).toLocaleString('zh-CN')}</text>`; }).join(''); const bars = items.map((item, i) => { const center = 39 + step * (i + .5), py = y(item.planned), ay = y(item.actual); return `<rect class="monthly-plan-bar" x="${center - width - 1}" y="${py}" width="${width}" height="${126 - py}"><title>${esc(item.name)} 计划 ${item.planned}</title></rect><rect class="monthly-actual-bar" x="${center + 1}" y="${ay}" width="${width}" height="${126 - ay}"><title>${esc(item.name)} 实际 ${item.actual}</title></rect><text class="monthly-brand-label" x="${center}" y="146" text-anchor="middle">${esc(item.shortName || item.name)}</text>`; }).join(''); const netKpi = net === undefined ? '' : `<div class="monthly-kpi daily-net-kpi">净流入 <b>${fmt(net)}</b><small>吨</small></div>`; return `<div class="monthly-meta"><span class="monthly-unit">单位：${esc(plan.unit || '吨')}</span><div class="monthly-legend"><span><i></i>计划调拨量</span><span><i class="actual"></i>实际调拨量</span></div></div><div class="monthly-kpis"><div class="monthly-kpi">完成率 <b>${completion.toFixed(1)}%</b></div><div class="monthly-kpi">偏差 <b>${variance.toLocaleString('zh-CN', { minimumFractionDigits: digits, maximumFractionDigits: digits })}</b><small>吨</small></div>${netKpi}</div><div class="monthly-chart"><svg viewBox="0 0 385 154" preserveAspectRatio="none"><defs><linearGradient id="planGradient" x1="0" y1="0" x2="0" y2="1"><stop class="monthly-plan-start" offset="0"></stop><stop class="monthly-plan-end" offset="1"></stop></linearGradient><linearGradient id="actualGradient" x1="0" y1="0" x2="0" y2="1"><stop class="monthly-actual-start" offset="0"></stop><stop class="monthly-actual-end" offset="1"></stop></linearGradient></defs>${grid}${bars}</svg></div>`; }
  function buildInventory() { const items = inventory.value.items || [], total = items.reduce((s, i) => s + n(i.quantity), 0) || n(inventory.value.total), share = items.reduce((s, i) => s + Math.max(0, n(i.percentage)), 0) || 1; let cursor = 0; const parts = items.map((i, x) => { const a = cursor; cursor += n(i.percentage) / share * 100; return `${i.color || palette[x]} ${a}% ${cursor}%`; }); const rows = items.map((i, x) => `<div class="brand" style="--c:${i.color || palette[x]}"><i></i><span>${esc(i.name)}</span><b>${fmt(i.percentage)}%</b><small>${fmt(i.quantity)}</small></div>`).join(''); return `${frame}<div class="panel-title">品牌库存结构</div><div class="inventory vue-inventory"><div class="vue-inventory-donut" style="background:conic-gradient(${parts.join(',') || '#153a5c 0 100%'})"><div class="inventory-center"><span>库存总量</span><b>${fmt(total)}<small>${esc(inventory.value.unit || '吨')}</small></b></div></div><div class="brand-list">${rows}</div></div>`; }
  function buildRisk() { const r = risk.value, total = r.running + r.idle + r.cleaning + r.alarm, shares = [r.running, r.idle, r.cleaning, r.alarm].map((v) => total ? v / total * 100 : 0), metrics = [['运行中', r.running, 'running-box'], ['空闲', r.idle, 'idle-box'], ['清洗/待检', r.cleaning, 'warn'], ['预警', r.alarm, 'alarm-box']].map((m, i) => `<div class="metric ${m[2]}"><span>${m[0]}</span><b>${m[1]}<small>个</small></b><span class="risk-metric-bar"><i style="--metric-share:${shares[i]}%"></i></span></div>`).join(''); return `${frame}<div class="bottom-title">储罐运行风险</div><div class="status-grid">${metrics}</div><div class="risk-overview-body"><div class="risk-loading"><div class="ring" style="background:conic-gradient(#36ddff 0 ${r.loadingRate}%,#16365d 0 100%)"><span class="ring-label">${fmt(r.loadingRate)}%<small>平均装载率</small></span></div></div><div class="risk-summary"><span>储罐总数</span><b>${total} 个</b><span>正常运行率</span><b class="normal">${fmt(shares[0])}%</b><span>风险罐占比</span><b class="risk">${fmt(shares[3])}%</b><span>待处理罐</span><b class="waiting">${r.cleaning + r.alarm} 个</b></div></div>`; }
  function buildEnergy() { const symbols = ['💧', '⚡', '💨'], states: Record<string, string> = { normal: '正常', warning: '警告', alarm: '报警' }, rows = energy.value.map((i, x) => `<div class="energy-rich"><span class="energy-type"><span class="energy-symbol">${symbols[x] || '◆'}</span><span>${esc(i.name)}</span></span><b>${fmt(i.value)} ${esc(i.unit)}</b><span>${fmt(i.plan, 0)} ${esc(i.unit)}</span><span>${esc(i.perUnit)}</span><em class="${i.state === 'normal' ? '' : 'warn'}">${states[i.state] || esc(i.state)}</em></div>`).join(''); return `${frame}<div class="bottom-title">公用能耗</div><div class="energy-head"><span></span><span>今日能耗</span><span>日计划</span><span>单位产品能耗</span><span>评价</span></div>${rows}`; }
  function gauge(label: string, value: number, unit: string, scale: number[], range: number[], warning: number, alarm: number) { const min = n(scale[0]), max = n(scale[1], 100), v = Math.max(min, Math.min(max, n(value))), state = v >= alarm ? 'is-alarm' : v >= warning || v < range[0] ? 'is-warning' : 'is-normal', point = (x: number, radius: number) => { const a = Math.PI + (x - min) / (max - min) * Math.PI; return [60 + radius * Math.cos(a), 62 + radius * Math.sin(a)]; }, path = (a: number, b: number, radius: number) => { const p = point(a, radius), q = point(b, radius); return `M${p[0]} ${p[1]}A${radius} ${radius} 0 0 1 ${q[0]} ${q[1]}`; }; return `<div class="env-reading"><div class="env-reading-copy"><div class="env-name">${label}</div><div class="env-value">${fmt(v)}<small>${unit}</small></div><span class="env-state ${state}">${state === 'is-normal' ? '正常' : state === 'is-warning' ? '预警' : '异常'}</span><div class="env-range">正常范围：${range[0]}~${range[1]}${unit}</div></div><svg class="industrial-gauge ${state}" viewBox="0 0 120 78" style="--needle-angle:${-90 + (v - min) / (max - min) * 180}deg"><path class="env-gauge-track" d="${path(min, max, 41)}"></path><path class="env-gauge-normal" d="${path(range[0], range[1], 41)}"></path><path class="env-gauge-progress" d="${path(min, v, 33)}"></path><text class="env-gauge-label" x="7" y="76">${min}</text><text class="env-gauge-label" x="60" y="8">${(min + max) / 2}</text><text class="env-gauge-label" x="113" y="76">${max}</text><g class="env-gauge-needle"><line x1="60" y1="62" x2="60" y2="32"></line></g><circle class="env-gauge-hub-outer" cx="60" cy="62" r="5"></circle><circle class="env-gauge-hub-inner" cx="60" cy="62" r="2.5"></circle></svg></div>`; }
  function buildEnvironment() { const e = environment.value; return `${frame}<div class="bottom-title">环境监测</div><div class="env-stack">${gauge('温度', e.temperature, '°C', e.temperatureScale, e.temperatureRange, e.temperatureWarning, e.temperatureAlarm)}${gauge('湿度', e.humidity, '%RH', e.humidityScale, e.humidityRange, e.humidityWarning, e.humidityAlarm)}</div>`; }
  function trendBrands() { return inventory.value.items.map((i, x) => ({ key: `brand-${x}`, name: i.name, color: i.color || palette[x], current: n(i.quantity) })); }
  // 品牌库存趋势:后端 mes3_maotai_cockpit_inventory_trend(日粒度),日期范围变化时重拉
  const trendPoints = ref<Array<{ date: string; items: Array<{ name: string; quantity: number }> }>>([]);
  let trendReqSeq = 0;
  async function loadTrend() {
    const seq = ++trendReqSeq;
    try {
      const pts = await getInventoryTrend(activeWorkshop.value, appliedStart.value, appliedEnd.value);
      if (seq === trendReqSeq) trendPoints.value = pts || [];
    } catch (e) { console.error('库存趋势加载失败', e); }
