  }
  function smooth(points: { x: number; y: number }[]) { return points.reduce((s, p, i) => !i ? `M${p.x},${p.y}` : `${s} C${(points[i - 1].x + p.x) / 2},${points[i - 1].y} ${(points[i - 1].x + p.x) / 2},${p.y} ${p.x},${p.y}`, ''); }
  function buildTrend() { const brands = trendBrands(), selected = brands.find((b) => b.key === trendBrand.value), color = selected?.color || '#2fe1ef', series = trendSeries(), values = series.map((p) => p.value), current = values.at(-1) || 0, first = values[0] || 0, change = current - first, pct = first ? change / first * 100 : 0, peak = values.length ? Math.max(...values) : 0, options = `<option value="all" ${trendBrand.value === 'all' ? 'selected' : ''}>全部品牌</option>${brands.map((b) => `<option value="${b.key}" ${trendBrand.value === b.key ? 'selected' : ''}>${esc(b.name)}</option>`).join('')}`; let chart = '<div class="inventory-trend-empty">暂无历史库存数据</div>'; if (series.length) { const min = Math.min(...values), max = Math.max(...values), pad = Math.max(10, (max - min) * .2), step = Math.max(10, Math.ceil((max - min + pad * 2) / 40) * 10), lo = Math.max(0, Math.floor((min - pad) / step) * step), hi = Math.max(lo + step * 4, Math.ceil((max + pad) / step) * step), x = (i: number) => series.length === 1 ? 374 : 62 + i * 624 / (series.length - 1), y = (v: number) => 137 - (v - lo) / (hi - lo) * 110, points = series.map((p, i) => ({ ...p, x: x(i), y: y(p.value) })), line = smooth(points), ticks = Array.from({ length: 5 }, (_, i) => { const v = hi - i * (hi - lo) / 4; return `<line class="inventory-trend-grid" x1="62" y1="${y(v)}" x2="686" y2="${y(v)}"></line><text class="inventory-trend-axis" x="55" y="${y(v) + 3}" text-anchor="end">${Math.round(v).toLocaleString('zh-CN')}</text>`; }).join(''), labels = Array.from(new Set([0, ...Array.from({ length: 5 }, (_, i) => Math.round((series.length - 1) * (i + 1) / 6)), series.length - 1])).map((i) => `<text class="inventory-trend-axis" x="${x(i)}" y="153" text-anchor="middle">${series[i].date}</text>`).join(''), maxI = values.indexOf(max), minI = values.indexOf(min), extremes = (maxI === minI ? [[maxI, '最高/最低']] : [[maxI, '最高'], [minI, '最低']]).map(([i, label]) => `<circle class="inventory-trend-dot" cx="${x(+i)}" cy="${y(valu