  function calendarHtml(side: string, view: Date) { const first = new Date(view.getFullYear(), view.getMonth(), 1).getDay(), days = new Date(view.getFullYear(), view.getMonth() + 1, 0).getDate(), cells = Array.from({ length: 42 }, (_, i) => { const day = i - first + 1; if (day < 1 || day > days) return '<span class="inventory-calendar-blank"></span>'; const iso = formatDate(new Date(view.getFullYear(), view.getMonth(), day)), classes = ['inventory-calendar-day']; if (iso >= draftStart.value && iso <= draftEnd.value) classes.push('is-in-range'); if (iso === draftStart.value) classes.push('is-range-start'); if (iso === draftEnd.value) classes.push('is-range-end'); if (iso === todayIso) classes.push('is-today'); return `<button class="${classes.join(' ')}" data-date="${iso}" data-side="${side}" ${iso > todayIso ? 'disabled' : ''}>${day}</button>`; }).join(''); return `<section class="inventory-calendar"><div class="inventory-calendar-head"><button class="inventory-calendar-nav" data-nav="-12" data-side="${side}">«</button><button class="inventory-calendar-nav" data-nav="-1" data-side="${side}">‹</button><div class="inventory-calendar-title">${view.getFullYear()}年 ${view.getMonth() + 1}月</div><button class="inventory-calendar-nav" data-nav="1" data-side="${side}">›</button><button class="inventory-calendar-nav" data-nav="12" data-side="${side}">»</button></div><div class="inventory-calendar-weekdays">${['日', '一', '二', '三', '四', '五', '六'].map((d) => `<span>${d}</span>`).join('')}</div><div class="inventory-calendar-days">${cells}</div></section>`; }
  function formatDate(d: Date) { return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; }
  function parseDate(s: string) { const [y, m, d] = s.split('-').map(Number); return new Date(y, m - 1, d); }
  function addDays(d: Date, x: number) { const r = new Date(d); r.setDate(r.getDate() + x); return r; }
  function monthStart(d: Date) { return new Date(d.getFullYear(), d.getMonth(), 1); }
  function dateDiff(a: string, b: string) { return Math.round((parseDate(b).getTime() - parseDate(a).getTime()) / 86400000); }
  async function toggleMonthMenu() {
    const opening = !monthMenuOpen.value;
    monthMenuOpen.value = opening;
    rangeMenuOpen.value = false;
    if (!opening) return;
    await nextTick();
    const menu = monthMenuRef.value, selected = menu?.querySelector<HTMLElement>('.monthly-period-option.is-selected');
    if (menu && selected) menu.scrollTop = Math.max(0, selected.offsetTop - (menu.clientHeight - selected.offsetHeight) / 2);
  }
  function selectMonth(month: number) { activeMonth.value = month; monthMenuOpen.value = false; loadMonthlyPlan(); }
  function closeMenus() { monthMenuOpen.value = false; if (rangeMenuOpen.value) cancelRange(); }
  function cancelRange() { draftStart.value = appliedStart.value; draftEnd.value = appliedEnd.value; rangeError.value = ''; rangeMenuOpen.value = false; }
  function onRootClick(e: MouseEvent) { const target = e.target as HTMLElement; if (target.closest('[data-range-toggle]')) { e.stopPropagation(); rangeMenuOpen.value ? cancelRange() : openRange(); return; } if (target.closest('.inventory-range-menu')) e.stopPropagation(); const brand = target.closest('[data-trend-brand]') as HTMLSelectElement | null; if (brand) { trendBrand.value = brand.value; return; } const quick = target.closest('[data-quick-days]') as HTMLElement | null; if (quick) { const days = n(quick.dataset.quickDays); draftEnd.value = todayIso; draftStart.value = formatDate(addDays(parseDate(todayIso), -(days - 1))); startView.value = monthStart(parseDate(draftStart.value)); endView.value = monthStart(parseDate(draftEnd.value)); return; } if (target.closest('[data-range-cancel]')) { cancelRange(); return; } if (target.closest('[data-range-apply]')) { const days = dateDiff(draftStart.value, draftEnd.value) + 1; if (days < 1 || days > 90) rangeError.value = '日期范围需为1—90天'; else { appliedStart.value = draftStart.value; appliedEnd.value = draftEnd.value; rangeMenuOpen.value = false; rangeError.value = ''; loadTrend(); } return; } const nav = target.closest('[data-nav]') as HTMLElement | null; if (nav) { const side = nav.dataset.side, step = n(nav.dataset.nav), source = side === 'start' ? startView.value : endView.value, next = new Date(source.getFullYear(), source.getMonth() + step, 1); if (side === 'start') startView.value = next; else endView.value = next; return; } const day = target.closest('[data-date]') as HTMLElement | null; if (day) { const iso = day.dataset.date!, side = day.dataset.side; if (side === 'start') { draftStart.value = iso; if (iso > draftEnd.value) draftEnd.value = iso; } else { draftEnd.value = iso; if (iso < draftStart.value) draftStart.value = iso; } return; } closeMenus(); }
  function onRootChange(e: Event) { const select = (e.target as HTMLElement).closest('[data-trend-brand]') as HTMLSelectElement | null; if (select) trendBrand.value = select.value; }
  function openRange() { draftStart.value = appliedStart.value; draftEnd.value = appliedEnd.value; startView.value = monthStart(parseDate(draftStart.value)); endView.value = monthStart(parseDate(draftEnd.value)); rangeMenuOpen.value = true; monthMenuOpen.value = false; }
  function onPointerMove(e: PointerEvent) {
