      const index = n(dailyBar.dataset.dailyIndex), item = dailyPlan.value.items?.[index], tip = dailyRoot.querySelector('.daily-tooltip') as HTMLElement | null;
      if (item && tip) {
        dailyRoot.querySelectorAll(`[data-daily-index="${index}"]`).forEach((bar) => bar.classList.add('is-hovered'));
