    tip.style.display = 'block'; tip.style.left = `${Math.max(4, Math.min(root.clientWidth - 145, e.clientX - rect.left + 10))}px`; tip.style.top = `${Math.max(4, e.clientY - rect.top - 48)}px`;
  }
  function hideTrendTooltip(e: PointerEvent) { const root = e.currentTarget as HTMLElement; root.querySelectorAll<HTMLElement>('.inventory-trend-tooltip,.daily-tooltip').forEach((tip) => tip.style.display = 'none'); root.querySelectorAll('.daily-chart .is-hovered').forEach((bar) => bar.classList.remove('is-hovered')); }

  async function loadCards() { const seq = ++requestSeq, results = await getCockpitCards(activeWorkshop.value); if (seq !== requestSeq) return { failed: 0, stale: true }; let applied = 0; const apply = (i: number, setter: (v: any) => void) => { const r = results[i]; if (r.status === 'fulfilled' && r.value) { setter(r.value); applied++; } }; apply(0, (v) => monthlyApi.value = v); apply(1, (v) => annual.value = v); apply(2, (v) => inventory.value = v); apply(3, (v) => material.value = v); apply(4, (v) => energy.value = Array.isArray(v) ? v : v.items || []); apply(5, (v) => risk.value = v); apply(6, (v) => environment.value = v); apply(7, (v) => transfer.value = v); apply(8, (v) => legacyTrend.value = v); if (applied) lastUpdated.value = new Date().toLocaleTimeString('zh-CN', { hour12: false }); return { failed: results.length - applied, stale: false }; }
  function schedulePoll() { if (pollTimer) clearTimeout(pollTimer); if (polling && !document.hidden) pollTimer = setTimeout(pollOnce, pollDelay); }
  async function pollOnce() { if (!polling || document.hidden) return; const result = await loadCards(); if (!polling || result.stale) return; failures = result.failed ? failures + 1 : 0; pollDelay = result.failed ? Math.min(300000 * 2 ** failures, 1800000) : 300000; schedulePoll(); }
  function startPolling() { stopPolling(); polling = true; failures = 0; pollDelay = 300000; void pollOnce(); }
  function stopPolling() { polling = false; requestSeq++; if (pollTimer) clearTimeout(pollTimer); pollTimer = undefined; }
