  function backToPreview() { router.push({ path: '/maotai/workshopPreview', query: { workshopIndex: String(activeWorkshop.value) } }); }
  async function toggleFullscreen() { if (!document.fullscreenElement) await document.documentElement.requestFullscreen(); else await document.exitFullscreen(); }
  function updateClock() { nowText.value = new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23', weekday: 'long' }).format(new Date()).replace(/\//g, '-'); }
  function onVisibilityChange() { if (document.hidden) { resumeWhenVisible = polling; if (polling) stopPolling(); } else if (resumeWhenVisible) { resumeWhenVisible = false; startPolling(); } }
  watch(() => route.query.workshopIndex, (v) => { const next = normalizeWorkshopIndex(v); if (next !== activeWorkshop.value) { activeWorkshop.value = next; startPolling(); } });
